(()=>{'use strict';
document.querySelectorAll('.interactive-explorer').forEach(root=>{const tabs=[...root.querySelectorAll('[role=tab]')],panels=[...root.querySelectorAll('[role=tabpanel]')];function activate(i){tabs.forEach((t,j)=>{t.setAttribute('aria-selected',String(j===i));t.tabIndex=j===i?0:-1;panels[j].hidden=j!==i})}tabs.forEach((t,i)=>{t.addEventListener('click',()=>activate(i));t.addEventListener('keydown',e=>{let next=i;if(e.key==='ArrowRight')next=(i+1)%tabs.length;else if(e.key==='ArrowLeft')next=(i-1+tabs.length)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();activate(next);tabs[next].focus()})})});
const query=document.querySelector('#variety-query');if(query){const cards=[...document.querySelectorAll('.variety-grid .variety-card')];query.addEventListener('input',()=>{const term=query.value.trim().toLocaleLowerCase('it');let count=0;cards.forEach(c=>{c.hidden=!c.textContent.toLocaleLowerCase('it').includes(term);if(!c.hidden)count++});document.querySelector('.variety-results').textContent=`${count} varietà trovate`;document.querySelector('.variety-empty').hidden=count>0})}
const dialog=document.querySelector('.video-dialog');if(dialog){let origin;document.querySelectorAll('.video-launch').forEach(b=>b.addEventListener('click',()=>{origin=b;dialog.querySelector('h2').textContent=b.dataset.title;const iframe=document.createElement('iframe');iframe.src=`https://www.youtube-nocookie.com/embed/${b.dataset.video}?autoplay=1&rel=0`;iframe.title=b.dataset.title;iframe.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';iframe.allowFullscreen=true;iframe.referrerPolicy='strict-origin-when-cross-origin';dialog.querySelector('.video-frame').replaceChildren(iframe);dialog.querySelector('.video-fallback').href=`https://www.youtube.com/watch?v=${b.dataset.video}`;dialog.showModal();document.body.style.overflow='hidden';dialog.querySelector('.video-close').focus()}));dialog.querySelector('.video-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{dialog.querySelector('.video-frame').replaceChildren();document.body.style.overflow='';origin?.focus()})}
})();

// Self-hosted silent video background.
(()=>{const video=document.querySelector('.company-background-video');if(!video)return;const btn=document.querySelector('.background-video-toggle');const reduced=matchMedia('(prefers-reduced-motion: reduce)');let userPaused=reduced.matches;video.muted=true;video.defaultMuted=true;function sync(){btn.textContent=video.paused?'▶ Riproduci':'Ⅱ Pausa';btn.setAttribute('aria-label',video.paused?'Riproduci il video di sfondo':'Metti in pausa il video di sfondo')}function start(){if(userPaused||document.hidden)return;video.play().then(sync).catch(sync)}btn.addEventListener('click',()=>{userPaused=!video.paused;if(userPaused)video.pause();else start();sync()});video.addEventListener('play',sync);video.addEventListener('pause',sync);if(reduced.matches){video.removeAttribute('autoplay');video.pause()}else start();new IntersectionObserver(entries=>{if(entries[0].isIntersecting)start();else video.pause()},{threshold:.05}).observe(video);document.addEventListener('visibilitychange',()=>{if(document.hidden)video.pause();else if(video.getBoundingClientRect().bottom>0)start()});reduced.addEventListener('change',()=>{userPaused=reduced.matches;if(userPaused)video.pause();else start();sync()});sync()})();
